actions.action:
// Economic nexus established - filing required
// VT uses "doing business" standard for income tax nexus
// Apportionment will be calculated by tables 7000-7500

// No nexus - no filing required
apportionment.state_tax = 0.0;
apportionment.state_refund_or_owed = apportionment.state_payments;

            // Calculate VT state additions
            double additions = 0.0;

            // VT requires addback of:
            // - Federal interest income (U.S. government obligations - taxable to VT)
            // - Interest on non-Vermont state and local bonds
            // - State income taxes deducted federally
            // - Certain federal depreciation differences

            // Example additions (would be calculated from entity fields):
            // additions += revenue.federal_bond_interest;
            // additions += revenue.other_state_bond_interest;
            // additions += result.state_taxes_deducted;

            apportionment.state_additions = additions;

            // Calculate VT state subtractions
            double subtractions = 0.0;

            // VT allows subtraction of:
            // - VT municipal bond interest (exempt for VT purposes)
            // - VT net operating loss deduction (if applicable)
            // - Certain dividend income deductions

            // Example subtractions (would be calculated from entity fields):
            // subtractions += revenue.vt_municipal_interest;
            // subtractions += result.vt_nol_deduction;
            // subtractions += result.vt_dividend_deduction;

            apportionment.state_subtractions = subtractions;

            // VT uses graduated rates: 6.0%, 7.0%, 8.5%
            // Brackets: $0-$10,000 | $10,001-$25,000 | Over $25,000

            double taxable_income = apportionment.state_taxable_income;
            double calculated_tax = 0.0;

            // Calculate tax using graduated brackets
            if (taxable_income <= apportionment.vt_bracket_threshold_1) {
              // All income in first bracket: 6.0% rate
              calculated_tax = taxable_income * apportionment.vt_tax_rate_tier1;
            } else if (taxable_income <= apportionment.vt_bracket_threshold_2) {
              // Income spans first two brackets
              // First $10,000 at 6.0%
              calculated_tax = apportionment.vt_bracket_threshold_1 * apportionment.vt_tax_rate_tier1;
              // Remainder at 7.0%
              calculated_tax += (taxable_income - apportionment.vt_bracket_threshold_1) * apportionment.vt_tax_rate_tier2;
            } else {
              // Income spans all three brackets
              // First $10,000 at 6.0%
              calculated_tax = apportionment.vt_bracket_threshold_1 * apportionment.vt_tax_rate_tier1;
              // Next $15,000 ($10,001-$25,000) at 7.0%
              calculated_tax += (apportionment.vt_bracket_threshold_2 - apportionment.vt_bracket_threshold_1) * apportionment.vt_tax_rate_tier2;
              // Remainder over $25,000 at 8.5%
              calculated_tax += (taxable_income - apportionment.vt_bracket_threshold_2) * apportionment.vt_tax_rate_tier3;
            }

            apportionment.vt_calculated_tax = calculated_tax;

            // Subtract VT state credits
            // VT offers various credits: R&D, affordable housing, renewable energy,
            // historic preservation, etc.
            apportionment.state_tax =
              Math.max(0.0, calculated_tax - apportionment.state_credits);

            // Calculate refund or amount owed
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;
